const expertise=['Bar Operations','Cocktail Development','Menu Engineering','Pricing','Cost Control','Team Training','Upselling','Guest Experience','Procurement','Operational Efficiency'];
function configureHotels(copy){for(const lang of ['pt','es','en']){const t=copy[lang],s=strategy[lang];Object.assign(t,{title:s.title,desc:s.desc,headline:s.headline,hero:s.hero,heroCta:s.cta,eyebrow:'Bar Performance · Guest Experience · '+(localLabel(lang,'Rentabilidade','Rentabilidad','Profitability')),opportunity:localLabel(lang,'O potencial que já está no seu hotel','El potencial que ya está en su hotel','The potential already inside your hotel'),intervention:localLabel(lang,'Serviços / do diagnóstico à operação','Servicios / del diagnóstico a la operación','Services / from diagnosis to delivery'),method:localLabel(lang,'O método','El método','Our approach')});t.services=s.services.map(x=>[...x,'']);t.types.push('Mystery Guest Audit',localLabel(lang,'Parceria de grupo hoteleiro','Colaboración con grupo hotelero','Hotel group partnership'));if(lang!=='en')t.faqs[2]=lang==='pt'?['Garantem um aumento de faturação?','Não. Definimos objetivos a partir do diagnóstico, da procura e dos dados da operação. O crescimento histórico do Cheers O Bar e a calculadora ilustrativa não são previsões nem garantias para hotéis.']:['¿Garantizan un aumento de facturación?','No. Definimos objetivos a partir del diagnóstico, la demanda y los datos de la operación. El crecimiento histórico de Cheers O Bar y la calculadora ilustrativa no son previsiones ni garantías para hoteles.'];}}
const list=items=>`<ul class="clean-list">${items.map(x=>`<li>${x}</li>`).join('')}</ul>`;
function auditSection(lang){const s=strategy[lang];return `<nav class="section-nav wrap" aria-label="${localLabel(lang,'Nesta página','En esta página','On this page')}"><a href="#audit">Mystery Guest</a><a href="#intervention">${localLabel(lang,'Serviços','Servicios','Services')}</a><a href="#case-study">Cheers O Bar</a><a href="#calculator">${localLabel(lang,'Simular potencial','Simular potencial','Explore potential')}</a><a href="#groups">${localLabel(lang,'Grupos hoteleiros','Grupos hoteleros','Hotel groups')}</a><a href="#about-rui">Rui Monteiro</a></nav><section class="section audit-section" id="audit"><div class="wrap"><span class="eyebrow">Mystery Guest Bar Audit / 1–2 ${localLabel(lang,'dias','días','days')}</span><h2>${s.auditTitle}</h2><p class="wide-lead">${s.auditIntro}</p><div class="split audit-columns"><div><h3>${localLabel(lang,'O que observamos','Qué observamos','What we observe')}</h3>${list(s.auditCheck)}</div><div class="audit-delivery"><h3>${localLabel(lang,'O que recebe','Qué recibe','What you receive')}</h3>${list(s.auditDelivery)}</div></div><p class="section-note">${s.auditNote}</p><div class="inline-cta"><p>${s.auditHook}</p><a class="btn" href="#contact" data-inquiry="audit">${s.cta} ${arrow}</a></div></div></section>`;}
function performanceSection(lang){const s=strategy[lang];return `<section class="section services" id="performance"><div class="wrap"><span class="eyebrow section-label">We make bars perform better.</span><h2>${s.revenue}</h2><div class="split performance-columns"><div><h3>${s.revenueLabel}</h3>${list(s.revenueItems)}</div><div><h3>${s.costLabel}</h3>${list(s.costItems)}</div></div><div class="split"><article><h3>${s.effTitle}</h3><p>${s.effText}</p></article><article><h3>${s.qualityTitle}</h3><p>${s.qualityText}</p></article></div></div></section>`;}
function caseSection(lang){const s=strategy[lang];return `<section class="section potential" id="case-study"><div class="wrap split"><div><span class="eyebrow">${s.caseLabel}</span><h2>${s.caseTitle}</h2><div class="big-number case-number">+100%</div><p class="case-result">${s.caseText}</p></div><div class="case-context"><h3>${s.caseLearn}</h3><p>${s.caseWork}</p><p class="case-note">${s.caseNote}</p></div></div></section>`;}
function cocktailSection(lang){const s=strategy[lang];return `<section class="section" id="cocktail-development"><div class="wrap split"><div><span class="eyebrow section-label">Cocktail Development</span><h2>${s.cocktailTitle}</h2></div><div><p class="event-lead">${s.cocktailText}</p><ul class="tag-list">${s.cocktailTags.map(x=>`<li>${x}</li>`).join('')}</ul></div></div></section><section class="section services" id="touchpoints"><div class="wrap"><h2>${s.touchTitle}</h2><div class="touch-grid">${s.touches.map(x=>`<article><h3>${x[0]}</h3><p>${x[1]}</p></article>`).join('')}</div></div></section>`;}
function groupSection(lang){const s=strategy[lang];return `<section class="section group-section" id="groups"><div class="wrap split"><div><span class="eyebrow">Multi-property / Portugal & Spain</span><h2>${s.groupTitle}</h2><p class="wide-lead">${s.groupText}</p><a class="btn" href="#contact" data-inquiry="group">${s.groupCTA} ${arrow}</a></div><div>${list(s.groupItems)}</div></div></section>`;}
function aboutSection(lang){const s=strategy[lang];return `<section class="section people" id="about-rui"><div class="wrap split"><div><span class="eyebrow section-label">Rui Monteiro / Founder · Cheers Experiences</span><h2>${s.aboutTitle}</h2><p class="about-training">${s.aboutTraining}</p></div><div><p>${s.aboutText}</p><p>${s.aboutOps}</p><p class="section-note">${s.aboutNote}</p></div></div><div class="wrap"><ul class="tag-list">${expertise.map(x=>`<li>${x}</li>`).join('')}</ul></div></section>`;}
let calculatorState={rooms:100,occupancy:75,guests:150,penetration:30,ticket:12,days:30,lift:5,ticketLift:10};
const calculatorFields=[['rooms',0,100000,1],['occupancy',0,100,.1],['guests',0,1000000,1],['penetration',0,100,.1],['ticket',0,100000,.01],['days',0,31,1],['lift',0,100,.1],['ticketLift',0,200,.1]];
function calculatePotential(v){if(calculatorFields.some(([k,min,max])=>v[k]===''||!Number.isFinite(Number(v[k]))||Number(v[k])<min||Number(v[k])>max))return null;const p=Math.min(100,Number(v.penetration)+Number(v.lift))/100;const baseline=v.guests*v.penetration/100*v.ticket*v.days;const simulated=v.guests*p*v.ticket*(1+v.ticketLift/100)*v.days;return {baseline,simulated,monthly:simulated-baseline,annual:(simulated-baseline)*12};}
function calculatorSection(lang){const s=strategy[lang];return `<section class="section" id="calculator"><div class="wrap"><div class="section-head"><div><span class="eyebrow section-label">${localLabel(lang,'Simulador de faturação','Simulador de facturación','Revenue simulator')}</span><h2>${s.calcTitle}</h2></div><p>${s.calcIntro}</p></div><div class="calculator-layout"><div><form id="calculator-form" class="calculator-fields">${calculatorFields.map(([key,min,max,step],i)=>`<label>${s.calcLabels[i]}<input name="${key}" type="number" inputmode="decimal" min="${min}" max="${max}" step="${step}" value="${calculatorState[key]}" required></label>`).join('')}</form><button type="button" class="estimate-button" id="estimate-guests">${s.calcEstimate}</button><p class="section-note">${s.calcHint}</p></div><div><div class="calculator-results" role="status" aria-live="polite" id="calculator-results"></div><p class="section-note">${s.calcFormula}</p></div></div><p class="simulation-notice">${s.calcDisclaimer}</p></div></section>`;}
function bindCalculator(lang){const s=strategy[lang],form=document.getElementById('calculator-form');function update(){const data=new FormData(form);calculatorFields.forEach(([k])=>calculatorState[k]=data.get(k));const result=calculatePotential(calculatorState);const out=document.getElementById('calculator-results');if(!result){out.textContent=s.calcInvalid;return;}const money=new Intl.NumberFormat(lang==='pt'?'pt-PT':lang==='en'?'en-GB':'es-ES',{style:'currency',currency:'EUR',maximumFractionDigits:0});out.innerHTML=['baseline','simulated','monthly','annual'].map((k,i)=>`<div class="calc-result ${i>1?'increment':''}"><span>${s.calcOutputs[i]}</span><strong>${money.format(result[k])}</strong></div>`).join('');}form.addEventListener('submit',e=>e.preventDefault());form.addEventListener('input',update);document.getElementById('estimate-guests').addEventListener('click',()=>{const r=form.elements.rooms.valueAsNumber,o=form.elements.occupancy.valueAsNumber;if(!Number.isFinite(r)||!Number.isFinite(o)||r<0||o<0||o>100)return;form.elements.guests.value=Math.round(r*o/100*2);update();});update();}
function updateMetadata(lang,isEvent){const t=isEvent?eventCopy[lang]:copy[lang],path=isEvent?'eventos.html':'index.html',url=`https://cheers.guru/${path}?lang=${lang}`;document.querySelector('link[rel="canonical"]').href=url;for(const [property,value] of [['og:title',t.title],['og:description',t.desc],['og:url',url],['og:locale',lang==='pt'?'pt_PT':lang==='en'?'en_GB':'es_ES']])document.querySelector(`meta[property="${property}"]`).content=value;document.getElementById('structured-data').textContent=JSON.stringify({'@context':'https://schema.org','@type':'ProfessionalService','name':'Cheers Experiences','url':url,'description':t.desc,'email':'sucessomacico@gmail.com','telephone':'+351927653087','areaServed':isEvent?['Viseu','Coimbra','Aveiro','Porto','Vila Real','Guarda','Algarve','Costa Blanca']:['Portugal','España'],'knowsLanguage':['pt','es','en'],'parentOrganization':{'@type':'Organization','name':'Sucesso Maciço, Lda.'}});}
